import numpy as np, time

def vec_svd(A, lam):
    B = A.astype(np.complex128, copy=True)
    n=B.shape[0]
    B.flat[::n+1] -= lam
    _,_,vh=np.linalg.svd(B)
    return vh[-1].conj()

def f_svd(A):
    vals=np.linalg.eigvals(A)
    lam=vals[np.argmax(np.abs(vals))]
    return lam, vec_svd(A, lam)

def vec_rows(A, lam):
    B=A.astype(np.complex128,copy=True); n=B.shape[0]; B.flat[::n+1]-=lam
    # use SVD fallback
    return vec_svd(A,lam)

