import numpy as np, time
from scipy.linalg.lapack import dgeev

def f_lap(A):
    wr, wi, vl, vr, info = dgeev(A, compute_vl=0, compute_vr=1, overwrite_a=0)
    mags = wr*wr + wi*wi
    i = int(np.argmax(mags))
    lam = wr[i] + 1j*wi[i]
    if wi[i] == 0:
        v = vr[:, i].astype(np.complex128)
    elif wi[i] > 0:
        v = vr[:, i].astype(np.complex128) + 1j*vr[:, i+1]
    else:
        v = vr[:, i-1].astype(np.complex128) - 1j*vr[:, i]
    return lam, v
for n in range(2,11):
    As=[np.random.normal(size=(n,n)).astype(np.float64) for _ in range(500)]
    def bench(f):
        ts=[]; ok=True
        for A in As:
            t=time.perf_counter(); lam,v=f(A); ts.append(time.perf_counter()-t)
            if not np.allclose(A@v, lam*v): ok=False; break
        return np.median(ts)*1e6, ok
    def f_np(A):
        w,V=np.linalg.eig(A); i=np.argmax(abs(w)); return w[i],V[:,i]
    print(n, 'lap', bench(f_lap), 'np', bench(f_np)[0])
